ArrayList <Mover> bouncers;

let i = 0; 
let bgcolor;
bgcolor=color(0,0,0,255);
//bgcolor=color(random(255),random(255),random(255),255);
let blu=color(0,0,255);
let rosso=color(255,0,0);
let verde=color(0,255,0);
let Nmovers=250;

function setup() {  // this is run once.   

    // set the background color
    background(bgcolor);

    // canvas createCanvas(aren't evaluated. only, please.)
    createCanvas(300, 300); 

    // smooth edges
    smooth();

    // limit the number of frames per second
    frameRate(30);

    // set the width of the line. 
    strokeWeight(12);

     bouncers = new ArrayList();

  for (i = 0; i < Nmovers; i++)
  {
    let m = new Mover();
    bouncers.add (m);
  }
  var m = bouncers.get(0);
  m.colore=rosso;
  m.speed=0.5;

} 

function draw() {  // this is run repeatedly.  

//background(bgcolor);
fill(bgcolor);
rect(0,0,width,height);

stroke(135);
strokeWeight(1);
line(0,0,0,height);
line(0,0,width,0);
line(0,height-1,width,height-1);
line(width-1,0,width-1,height);

 var i = 0;
  while (i < bouncers.size () )
  {
    var m = bouncers.get(i);
    m.update();
    m.interact(bouncers);


    i = i + 1;
  }
}

class Mover
{
  direction;
  location;

  speed;
  SPEED;

  ellipseSize;

  colore;
  timeCounter;


  constructor() // Constructor = setup of let Class
  {
    setRandomValues();
  }

  constructor(x, y) // Constructor = setup of let Class
  {
    setRandomValues ();
  }

  // SET ---------------------------





  function setRandomValues()
  {
    location = new PVector (random (width), random (height));
    ellipseSize = 6;

    let angle = random (TWO_PI);
    direction = new PVector (cos (angle), sin (angle));

    speed = random (0.1, 0.5);
    SPEED = speed;

    colore=blu;
    timeCounter = 0;

  }


  // GENEREL ------------------------------


  function update()
  {
    {
      // speed = SPEED * 0.7;
      move();
      checkEdgesAndBounce();
      //timeCounter=timeCounter+1;
      //if(timeCounter>20000){timeCounter=0;}
      if(colore==rosso){timeCounter=timeCounter+1;}
      //if(colore==verde){timeCounter=0;}
      //if(colore==blu){timeCounter=0;}
      if((timeCounter>110)&&(colore==rosso)){
          colore=verde;
          timeCounter=0;
          }
    }
    disp();
  }

  function checkEdgesAndBounce()
  {
    let radius = ellipseSize / 2;

    if (location.x < radius )
    {
      location.x = radius ;
      direction.x = direction.x * -1;
    }
    else if (location.x > width-radius )
    {
      location.x = width-radius ;
      direction.x *= -1;
    }

    if (location.y < radius )
    {
      location.y = radius ;
      direction.y *= -1;
    }
    else if (location.y > height-radius )
    {
      location.y = height-radius ;
      direction.y *= -1;
    }
  }


  // MOVE -----------------------------------------

  function move()
  {

    let velocity = direction.get();
    velocity.mult (speed);
    location.add (velocity);
  }

  // DISPLAY ---------------------------------------------------------------

  function disp()
  {
  noStroke();
    fill (colore);
    ellipse (location.x, location.y, ellipseSize, ellipseSize);
    //text(timeCounter,location.x+6, location.y+6)
  }


function interact(ArrayList <Mover> boids)
  {

    let other;
    let otherSize ;

    let d1 = direction.get();
    let speed1=speed;
    let v1 = PVector.mult (d1,speed1);


    for (i = 0; i < boids.size(); i++)
    {
      other = boids.get(i).location;
      otherSize = boids.get(i).ellipseSize;

      if(location!=other){

      let d2 = boids.get(i).direction;
      let speed2=boids.get(i).speed;
      let v2 = PVector.mult (d2,speed2);


      let distance = PVector.dist(other, location);



      if (distance < 0.5*(ellipseSize+otherSize)) {
          cOther=boids.get(i).colore;
          if((colore==blu) && (cOther==rosso)){
              colore=rosso;
              timeCounter=0;
              }
          if((colore==rosso) && (cOther==blu)){
              boids.get(i).colore=rosso;
              boids.get(i).timeCounter=0;
              }

          let Connection=PVector.sub(other,location);
          Connection.normalize();
          let scarto= new PVector;
          scarto.x=Connection.x;
          scarto.y=Connection.y;
          scarto.mult(0.5*(ellipseSize+otherSize)-distance)
          location.sub(scarto);
          let v1pm=PVector.dot(v1,Connection);
          let v2pm=PVector.dot(v2,Connection);
          let v1p=PVector.mult(Connection,v1pm);
          let v2p=PVector.mult(Connection, v2pm);
          let Deltav=PVector.sub(v1p,v2p);
          v1.sub(Deltav);
          v2.add(Deltav);
          speed=min(v1.mag(),10);
          speed2=v2.mag();
          d1.set(v1);
          d1.normalize();
          d2.set(v2);
          d2.normalize();   
          direction.x=d1.x;
          direction.y=d1.y;
          boids.get(i).direction.x=d2.x;
          boids.get(i).direction.y=d2.y;   
          boids.get(i).speed=min(speed2,10);   
          }
          }

      }
    }


}


function mouseClicked(){
    //bgcolor=color(random(255),random(255),random(255));

  for (i = 0; i < Nmovers; i++)
  {
      loc = bouncers.get(i).location;
      size = bouncers.get(i).ellipseSize;
      let mclick = new PVector((window.simulatedMouseX !== undefined ? window.simulatedMouseX : (typeof sub_bass !== 'undefined' ? map(sub_bass, 0, 1, width*0.1, width*0.9) : (typeof live_centroid !== 'undefined' ? map(live_centroid, 100, 4000, 0, width) : mouseX))),(window.simulatedMouseY !== undefined ? window.simulatedMouseY : (typeof percussive !== 'undefined' ? map(percussive, 0, 1, height, 0) : (typeof roughness !== 'undefined' ? map(roughness, 0, 1, height*0.2, height*0.8) : mouseY))));
      var distance = PVector.dist(loc, mclick);
    if(distance<=size){
        bouncers.get(i).colore=color(rosso);
        bouncers.get(i).timeCounter=0;
        }
  }
    }

